import 'package:flutter/material.dart';
class CategoryCard extends StatelessWidget{final String title;final IconData icon;final VoidCallback? onTap;const CategoryCard({super.key,required this.title,required this.icon,this.onTap});@override Widget build(BuildContext c)=>Card(child:InkWell(onTap:onTap,child:Padding(padding:const EdgeInsets.all(14),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(icon,size:34),const SizedBox(height:8),Text(title,textAlign:TextAlign.center)]))));}
